/**
 * A hierarchy opened level by level, with one item picked (`design/components/tree.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tree.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Each,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/tree.module.css'
import Spinner from './Spinner'
import TreeNode from './TreeNode'

export interface TreeItem {
  /** Unique in the tree. `change`, `expandedChange` and `loadMore` report it. */
  id: string
  label: string
  /** One supporting line under the label. */
  description?: string
  /** The items under it. An item with one or more is a branch. */
  children?: TreeItem[]
  /**
   * A branch whose items the app loads when it is first opened. With no `children` the
   * branch opens onto nothing until the app passes them.
   */
  hasChildren?: boolean
  /** The branch's level is loading. An open branch draws one busy row under itself. */
  loading?: boolean
  /** The branch has more items than `children` holds: a last row asks for them. */
  hasMore?: boolean
  /** The item takes no key and no press, the arrow keys pass over it, and a branch stays closed. */
  disabled?: boolean
}

export interface TreeMessages {
  /** What a level says while it loads. */
  loading: string
  /** The row that asks for more of a level. */
  loadMore: string
}

export interface TreeProps {
  /**
   * The branches open at first, while the tree holds the set.
   */
  defaultExpanded?: ReadonlySet<string>
  /**
   * The item selected at first, while the tree holds the selection.
   */
  defaultValue?: string
  /**
   * The open branches by id. Controlled when given; without it the tree holds the set.
   */
  expanded?: ReadonlySet<string>
  /**
   * The top level has more items than `items` holds: a last row asks for them.
   */
  hasMore?: boolean
  /**
   * The top level.
   */
  items: TreeItem[]
  /**
   * Names the tree for a reader: "Organization units", not "Tree".
   */
  label: string
  /**
   * The top level is loading, as an item's `loading` says of its own level.
   */
  loading?: boolean
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: TreeMessages
  /**
   * Called with the id of the item a reader selects.
   */
  onChange?: (id: string) => void
  /**
   * Called with the next set of open branches, controlled or not.
   */
  onExpandedChange?: (next: ReadonlySet<string>) => void
  /**
   * Called with a branch's id, or `null` for the top level, when a reader asks for more.
   */
  onLoadMore?: (parentId: string | null) => void
  /**
   * The selected item's id. Controlled when given, and `null` selects nothing.
   */
  value?: string | null
}

/** A hierarchy opened level by level, with one item picked. */
export default function Tree(given: TreeProps): JSX.Element {
  const props = mergeProps(
    {
      loading: false,
      hasMore: false,
      messages: (() => ({ loading: 'Loading', loadMore: 'Load more' }))(),
    } as Defaults<TreeProps, 'loading' | 'hasMore' | 'messages'>,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const ownExpanded = createCell(props.defaultExpanded ?? new Set<string>())
    const ownValue = createCell((props.defaultValue ?? null) as string | null)
    const placed = createCell(false)
    const held = createCell(false)
    const asked = createCell(null as { parent: string | null; count: number } | null)
    const moving = createCell(false)
    const root = elementRef<HTMLElement>()
    const open = createDerived(() => props.expanded ?? ownExpanded.value)
    const selected = createDerived(() => (props.value === undefined ? ownValue.value : props.value))
    const shownItems = createDerived(() =>
      (() => {
        const seen: TreeItem[] = []
        const walk = (level: readonly TreeItem[]): void => {
          for (const item of level) {
            seen.push(item)
            if (item.disabled !== true && open.value.has(item.id)) walk(item.children ?? [])
          }
        }
        walk(props.items)
        return seen
      })(),
    )
    const branchOf = createDerived(() => (id: string): void => {
      const item = shownItems.value.find((candidate) => candidate.id === id)
      if ((item?.children?.length ?? 0) === 0 && item?.hasChildren !== true)
        throw new Error(`"${item?.label ?? id}" is not a branch, so it does not open or close.`)
    })
    const rowsOf = createDerived(
      () =>
        (tree: HTMLElement): HTMLElement[] =>
          Array.from(
            tree.querySelectorAll<HTMLElement>('[role="treeitem"]:not([aria-disabled="true"])'),
          ),
    )
    const parentOf = createDerived(
      () =>
        (row: Element): string | null =>
          row.parentElement?.closest('[role="treeitem"]')?.getAttribute('data-tree-item') ?? null,
    )
    const levelOf = createDerived(
      () =>
        (tree: HTMLElement, parent: string | null): Element | null =>
          parent === null
            ? tree
            : (Array.from(tree.querySelectorAll('[role="treeitem"]'))
                .find((row) => row.getAttribute('data-tree-item') === parent)
                ?.querySelector(':scope > [role="group"]') ?? null),
    )
    const itemsIn = createDerived(
      () =>
        (list: Element): HTMLElement[] =>
          Array.from(list.children).filter(
            (child): child is HTMLElement =>
              child instanceof HTMLElement &&
              child.matches('[role="treeitem"]') &&
              !child.matches('[data-tree-part="more"]'),
          ),
    )
    const stopOf = createDerived(() => (tree: HTMLElement): HTMLElement | null => {
      const rows = rowsOf.value(tree)
      const now = placed.value
        ? rows.find((row) => row.getAttribute('tabindex') === '0')
        : undefined
      return (
        now ?? rows.find((row) => row.getAttribute('aria-selected') === 'true') ?? rows[0] ?? null
      )
    })
    const rove = createDerived(() => (tree: HTMLElement, stop: HTMLElement | null) => {
      for (const row of Array.from(tree.querySelectorAll<HTMLElement>('[role="treeitem"]'))) {
        if (row !== stop && row.getAttribute('aria-disabled') === 'true') {
          row.removeAttribute('tabindex')
          continue
        }
        const wanted = row === stop ? '0' : '-1'
        if (row.getAttribute('tabindex') !== wanted) row.setAttribute('tabindex', wanted)
      }
    })
    const settle = createDerived(() => () => {
      const tree = root.value as HTMLElement | null
      if (tree === null) return
      const lost = held.value && !tree.contains(document.activeElement)
      const request = asked.value
      let to: HTMLElement | null = null
      if (request !== null) {
        const list = levelOf.value(tree, request.parent)
        const found = list === null ? [] : itemsIn.value(list)
        if (list === null) asked.value = null
        else if (found.length > request.count) {
          if (held.value)
            to =
              found
                .slice(request.count)
                .find((row) => row.matches('[role="treeitem"]:not([aria-disabled="true"])')) ??
              stopOf.value(tree)
          asked.value = null
        }
      }
      if (to === null && lost) to = stopOf.value(tree)
      if (to === null) {
        rove.value(tree, stopOf.value(tree))
        return
      }
      rove.value(tree, to)
      moving.value = true
      to.focus()
      moving.value = false
    })
    const ask = createDerived(() => (row: HTMLElement) => {
      const list = row.parentElement
      if (list === null || row.getAttribute('aria-busy') === 'true') return
      const parent = parentOf.value(row)
      asked.value = { parent, count: itemsIn.value(list).length }
      props.onLoadMore?.(parent)
    })
    const toggle = createDerived(() => (id: string) => {
      const next = new Set(open.value)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      ownExpanded.value = next
      props.onExpandedChange?.(next)
    })
    const choose = createDerived(() => (id: string) => {
      if (id === selected.value) return
      ownValue.value = id
      props.onChange?.(id)
    })
    const focusIn = createDerived(() => (event: FocusEvent) => {
      const tree = root.value as HTMLElement | null
      const row =
        event.target instanceof Element
          ? event.target.closest<HTMLElement>('[role="treeitem"]')
          : null
      if (tree === null || row === null) return
      held.value = true
      placed.value = true
      const request = asked.value
      if (
        !moving.value &&
        !(
          request !== null &&
          row.matches('[data-tree-part="more"]') &&
          parentOf.value(row) === request.parent
        )
      )
        asked.value = null
      rove.value(tree, row)
    })
    const focusOut = createDerived(() => (event: FocusEvent) => {
      const tree = root.value as HTMLElement | null
      const row = event.target
      queueMicrotask(() => {
        if (tree === null || !(row instanceof Element) || !row.isConnected) return
        if (!tree.contains(document.activeElement)) held.value = false
      })
    })
    const keyDown = createDerived(() => (event: KeyboardEvent) => {
      const tree = root.value as HTMLElement | null
      const here =
        event.target instanceof Element
          ? event.target.closest<HTMLElement>('[role="treeitem"]')
          : null
      if (tree === null || here === null || event.altKey || event.ctrlKey || event.metaKey) return
      const rows = rowsOf.value(tree)
      const at = rows.indexOf(here)
      const rtl = getComputedStyle(tree).direction === 'rtl'
      const inward = rtl ? 'ArrowLeft' : 'ArrowRight'
      const outward = rtl ? 'ArrowRight' : 'ArrowLeft'
      const id = here.matches('[role="treeitem"]:not([aria-disabled="true"])')
        ? here.getAttribute('data-tree-item')
        : null
      const state = here.getAttribute('aria-expanded')
      let to: HTMLElement | null | undefined = null
      switch (event.key) {
        case 'ArrowDown':
          to = rows[at + 1]
          break
        case 'ArrowUp':
          to = at > 0 ? rows[at - 1] : null
          break
        case 'Home':
          to = rows[0]
          break
        case 'End':
          to = rows[rows.length - 1]
          break
        case inward:
          if (id !== null && state === 'false') toggle.value(id)
          else if (state === 'true')
            to = here.querySelector<HTMLElement>(
              ':scope > [role="group"] > [role="treeitem"]:not([aria-disabled="true"])',
            )
          break
        case outward:
          if (id !== null && state === 'true') toggle.value(id)
          else
            to = here.parentElement?.closest<HTMLElement>(
              '[role="treeitem"]:not([aria-disabled="true"])',
            )
          break
        case 'Enter':
        case ' ':
          if (here.matches('[data-tree-part="more"]')) ask.value(here)
          else if (id !== null) choose.value(id)
          break
        default:
          return
      }
      event.preventDefault()
      if (to === null || to === undefined) return
      rove.value(tree, to)
      to.focus()
    })
    const press = createDerived(() => (event: MouseEvent) => {
      const target = event.target instanceof Element ? event.target : null
      const row = target?.closest('[data-tree-part="row"]')?.parentElement ?? null
      if (
        target === null ||
        row === null ||
        !row.matches('[role="treeitem"]:not([aria-disabled="true"])')
      )
        return
      const id = row.getAttribute('data-tree-item')
      if (row.matches('[data-tree-part="more"]')) ask.value(row)
      else if (id === null) return
      else if (target.closest('[data-tree-part="toggle"]') !== null) toggle.value(id)
      else choose.value(id)
    })
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const run = () => {
        settle.value()
      }
      const mutation =
        typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
      for (const element of [root.value])
        if (element)
          mutation?.observe(element, {
            childList: true,
            characterData: true,
            subtree: true,
            attributeFilter: ['aria-selected', 'aria-disabled'],
          })
      release1 = () => {
        mutation?.disconnect()
      }
      run()
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = agentMember({
        member: 'Tree',
        element: () => root.value,
        state: () => ({
          value: selected.value ?? null,
          expanded: [...open.value],
          items: shownItems.value.map((item) => ({
            id: item.id,
            label: item.label,
            ...(item.disabled === true ? { disabled: true } : {}),
          })),
          loading: props.loading,
        }),
        actions: {
          choose: { argument: 'id', run: (value) => choose.value(value) },
          expand: {
            argument: 'id',
            run: (value) => (branchOf.value(value), open.value.has(value) || toggle.value(value)),
          },
          collapse: {
            argument: 'id',
            run: (value) => (branchOf.value(value), open.value.has(value) && toggle.value(value)),
          },
        },
      })
      release2 = () => {
        ran()
      }
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    return (
      <ul
        class={styles.root}
        role="tree"
        aria-label={props.label}
        aria-busy={props.loading ? true : undefined}
        data-member="tree"
        onfocusin={($event: FocusEvent) => focusIn.value($event)}
        onfocusout={($event: FocusEvent) => focusOut.value($event)}
        onkeydown={($event: KeyboardEvent) => keyDown.value($event)}
        onclick={($event: MouseEvent) => press.value($event)}
        ref={root.attach}
      >
        <Each of={props.items} by={(child) => child.id} renew>
          {(child) => (
            <TreeNode
              item={child}
              level={0}
              open={open.value}
              selected={selected.value}
              messages={props.messages}
            />
          )}
        </Each>
        {props.hasMore ? (
          <li
            class={styles.item}
            role="treeitem"
            aria-labelledby={`${uid}-more`}
            aria-selected="false"
            aria-busy={props.loading ? true : undefined}
            data-tree-part="more"
          >
            <div
              class={styles.row}
              style={{ '--pm-tree-level': 0 }}
              data-tree-part="row"
              data-busy={props.loading ? '' : undefined}
            >
              <span class={styles.slot}>
                {props.loading ? <Spinner size="sm" label={props.messages.loading} /> : null}
              </span>
              <span class={styles.text}>
                <span class={styles.more} id={`${uid}-more`}>
                  {props.loading ? props.messages.loading : props.messages.loadMore}
                </span>
              </span>
            </div>
          </li>
        ) : props.loading ? (
          <li class={styles.item} role="none">
            <div class={styles.row} style={{ '--pm-tree-level': 0 }} data-busy={''}>
              <span class={styles.slot}>
                <Spinner size="sm" label={props.messages.loading} />
              </span>
              <span class={styles.text}>
                <span class={styles.status} aria-hidden="true">
                  {props.messages.loading}
                </span>
              </span>
            </div>
          </li>
        ) : null}
      </ul>
    )
  })
}
